use std :: fmt :: { Display , Formatter } ; use std :: hash :: Hasher ; use std :: path :: PathBuf ; use std :: time :: { Duration , SystemTime , UNIX_EPOCH } ; use serde :: { Deserialize , Serialize } ; use uuid :: Uuid ; use super :: * ; impl Snapshot { pub fn create (path : PathBuf) -> anyhow :: Result < Self > { let path = match path . canonicalize () { Ok (p) => p , Err (_) => { if path . is_absolute () { path } else { anyhow :: bail ! ("Path must be absolute. Please provide an absolute path starting with '/' (Unix) or 'C:\\' (Windows)") ; } } } ; let timestamp = SystemTime :: now () . duration_since (UNIX_EPOCH) ? ; Ok (Self { id : SnapshotId :: new () , timestamp , path : path . display () . to_string () , }) } # [doc = " Create a hash of a file path for storage"] pub fn path_hash (& self) -> String { let mut hasher = fnv_rs :: Fnv64 :: default () ; hasher . write (self . path . as_bytes ()) ; format ! ("{:x}" , hasher . finish ()) } # [doc = " Create a snapshot filename from a path and timestamp"] pub fn snapshot_path (& self , cwd : Option < PathBuf >) -> PathBuf { let datetime = UNIX_EPOCH + self . timestamp ; let formatted_time = chrono :: DateTime :: < chrono :: Utc > :: from (datetime) . format ("%Y-%m-%d_%H-%M-%S-%9f") . to_string () ; let filename = format ! ("{formatted_time}.snap") ; let path = PathBuf :: from (self . path_hash ()) . join (PathBuf :: from (filename)) ; if let Some (cwd) = cwd { cwd . join (path) } else { path } } }